function splitEvenly(totalCents, people) {
  if (!Number.isInteger(people) || people < 1) {
    throw new RangeError('people must be a positive integer');
  }
  const base = Math.floor(totalCents / people);
  const remainder = totalCents % people;
  return Array.from({ length: people }, (_, i) => (i < remainder ? base + 1 : base));
}

// Computes each person's balance in cents from a list of expenses.
// Positive: the group owes them. Negative: they owe the group.
// Each expense is { paidBy, amountCents, splitAmong: [names] }.
// - The payer is credited the full amount.
// - Each person in splitAmong is debited their share from splitEvenly
//   (leftover cents go to the first names in the list).
// - Balances accumulate across expenses and always add up to zero.
function computeBalances(expenses) {
  const balances = {};
  for (const { paidBy, amountCents, splitAmong } of expenses) {
    const shares = splitEvenly(amountCents, splitAmong.length);
    balances[paidBy] = (balances[paidBy] ?? 0) + amountCents;
    splitAmong.forEach((name, i) => {
      balances[name] = (balances[name] ?? 0) - shares[i];
    });
  }
  return balances;
}

