const sum = (balances) => Object.values(balances).reduce((a, b) => a + b, 0);

describe('computeBalances', () => {
  test('credits the payer and debits everyone their share', () => {
    const balances = computeBalances([
      { paidBy: 'Ana', amountCents: 3000, splitAmong: ['Ana', 'Ben', 'Cai'] },
    ]);

    expect(balances).toEqual({ Ana: 2000, Ben: -1000, Cai: -1000 });
  });

  test('balances add up to zero when the bill does not divide evenly', () => {
    const balances = computeBalances([
      { paidBy: 'Ana', amountCents: 1000, splitAmong: ['Ana', 'Ben', 'Cai'] },
    ]);

    expect(balances).toEqual({ Ana: 666, Ben: -333, Cai: -333 });
    expect(sum(balances)).toBe(0);
  });

  test('accumulates several expenses paid by the same person', () => {
    const balances = computeBalances([
      { paidBy: 'Ana', amountCents: 2000, splitAmong: ['Ana', 'Ben'] },
      { paidBy: 'Ana', amountCents: 1000, splitAmong: ['Ana', 'Ben'] },
    ]);

    expect(balances).toEqual({ Ana: 1500, Ben: -1500 });
  });
});
